\begin{tikzpicture}
\definecolor{curveBlue}{HTML}{268CFF}
\begin{axis}[width=10cm,height=5cm,axis lines=middle,axis line style={black,->},xlabel={$x$},ylabel={$y$},label style={font=\fontsize{10}{12}\selectfont,text=black},tick label style={font=\fontsize{8.5}{10}\selectfont,text=black},xmin=-6.7,xmax=6.7,ymin=-1.4,ymax=1.4,xtick={-6.283185,-3.141593,0,3.141593,6.283185},xticklabels={$-2\pi$,$-\pi$,$0$,$\pi$,$2\pi$},ytick={-1,1},clip=true]
